ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ8 担当内諾"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "8-1:担当者に内諾をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "8-2:その後の工程、進め方について、担当者と打ち合わせを行った。")),
                NOT(INCLUDES(CompletionBasis__c, "8-3:担当役員へ提案実施のアポイントが取れた。"))
            )
        )
    )
)
